import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
.visible .entry conv_transpose3d_kernel(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .s32 n_batches,
    .param .s32 in_channels,
    .param .s32 out_channels,
    .param .s32 in_depth,
    .param .s32 in_height,
    .param .s32 in_width,
    .param .s32 out_depth,
    .param .s32 out_height,
    .param .s32 out_width,
    .param .s32 kernel_size,
    .param .s32 has_bias
)
{
    .shared .align 16 .b8 smem_in[15552];
    .shared .align 16 .b8 smem_w[3456];
    .reg .pred %p0, %p1, %p_inb, %p_k3;
    .reg .pred %p_done, %p_ci, %p_kz, %p_ky, %p_kx;
    .reg .pred %p_zlo, %p_zhi, %p_ylo, %p_yhi, %p_xlo, %p_xhi, %p_bias;
    .reg .b32 %r_ntid, %r_ctaid, %r_tid0, %r_tid, %r_total, %r_tmp, %r_tmp2;
    .reg .b32 %r_ox, %r_oy, %r_oz, %r_co, %r_bn;
    .reg .b32 %r_N, %r_CI, %r_CO, %r_D, %r_H, %r_W, %r_DO, %r_HO, %r_WO, %r_K, %r_BIAS;
    .reg .b32 %r_ci, %r_kz, %r_ky, %r_kx, %r_z, %r_y, %r_x;
    .reg .b32 %r_off, %r_woff, %r_hw, %r_dhw, %r_chw;
    .reg .b32 %r_txT, %r_tyT, %r_txtile, %r_tytile, %r_oy0, %r_ox0, %r_ty, %r_tx;
    .reg .b32 %r_ci0, %r_chunk, %r_idx, %r_limit, %r_c, %r_rem, %r_r2, %r_row, %r_col;
    .reg .b32 %r_shin, %r_shw, %r_ain, %r_sbase, %r_rowoff, %r_sidx, %r_widx;
    .reg .b32 %r_co0, %r_cog, %r_COG, %r_j, %r_wbase;
    .reg .b64 %xptr, %wptr, %bptr, %yptr, %addr, %waddr, %baddr, %yaddr;
    .reg .f32 %acc, %acc0, %acc1, %acc2, %acc3, %acc4, %acc5, %acc6, %acc7, %xv, %wv, %bv, %wv0, %wv1, %wv2, %wv3, %wv4, %wv5, %wv6, %wv7;
    ld.param.u64 %xptr, [x_ptr];
    ld.param.u64 %wptr, [w_ptr];
    ld.param.u64 %bptr, [b_ptr];
    ld.param.u64 %yptr, [y_ptr];
    ld.param.s32 %r_N, [n_batches];
    ld.param.s32 %r_CI, [in_channels];
    ld.param.s32 %r_CO, [out_channels];
    ld.param.s32 %r_D, [in_depth];
    ld.param.s32 %r_H, [in_height];
    ld.param.s32 %r_W, [in_width];
    ld.param.s32 %r_DO, [out_depth];
    ld.param.s32 %r_HO, [out_height];
    ld.param.s32 %r_WO, [out_width];
    ld.param.s32 %r_K, [kernel_size];
    ld.param.s32 %r_BIAS, [has_bias];
    setp.eq.s32 %p_k3, %r_K, 3;
    @!%p_k3 bra $D_setup;
    // ============================================================
    // Tiled path (K == 3, stride 1, pad 0): each CTA computes one
    // 16x16 output tile for a fixed (batch, out_z) and a GROUP of
    // 8 output channels. Output tiling improvement: the output-channel
    // tile is widened from 4 to 8 channels per CTA so the staged
    // 18x18x(4 cin x 3 kz) input patch in shared memory is reused
    // across 8 output channels via register blocking (acc0..acc7).
    // This halves the CTA count and cuts redundant global input
    // traffic ~2x versus the previous 4-channel grouping.
    // ============================================================
    mov.u32 %r_shin, smem_in;
    mov.u32 %r_shw, smem_w;
    mov.u32 %r_ctaid, %ctaid.x;
    mov.u32 %r_tid, %tid.x;
    add.s32 %r_txT, %r_WO, 15;
    shr.s32 %r_txT, %r_txT, 4;
    add.s32 %r_tyT, %r_HO, 15;
    shr.s32 %r_tyT, %r_tyT, 4;
    add.s32 %r_COG, %r_CO, 7;
    shr.s32 %r_COG, %r_COG, 3;
    rem.s32 %r_cog, %r_ctaid, %r_COG;
    div.s32 %r_tmp, %r_ctaid, %r_COG;
    rem.s32 %r_txtile, %r_tmp, %r_txT;
    div.s32 %r_tmp, %r_tmp, %r_txT;
    rem.s32 %r_tytile, %r_tmp, %r_tyT;
    div.s32 %r_tmp, %r_tmp, %r_tyT;
    rem.s32 %r_oz, %r_tmp, %r_DO;
    div.s32 %r_bn, %r_tmp, %r_DO;
    shl.b32 %r_co0, %r_cog, 3;
    shl.b32 %r_ox0, %r_txtile, 4;
    shl.b32 %r_oy0, %r_tytile, 4;
    shr.s32 %r_ty, %r_tid, 4;
    and.b32 %r_tx, %r_tid, 15;
    add.s32 %r_oy, %r_oy0, %r_ty;
    add.s32 %r_ox, %r_ox0, %r_tx;
    setp.lt.s32 %p0, %r_oy, %r_HO;
    setp.lt.s32 %p1, %r_ox, %r_WO;
    and.pred %p_inb, %p0, %p1;
    mov.f32 %acc0, 0f00000000;
    mov.f32 %acc1, 0f00000000;
    mov.f32 %acc2, 0f00000000;
    mov.f32 %acc3, 0f00000000;
    mov.f32 %acc4, 0f00000000;
    mov.f32 %acc5, 0f00000000;
    mov.f32 %acc6, 0f00000000;
    mov.f32 %acc7, 0f00000000;
    mov.s32 %r_ci0, 0;
$L_chunk_loop:
    setp.lt.s32 %p0, %r_ci0, %r_CI;
    @!%p0 bra $L_epilogue;
    sub.s32 %r_chunk, %r_CI, %r_ci0;
    min.s32 %r_chunk, %r_chunk, 4;
    // ---- stage input patch (zero-filled halo) into shared ----
    mul.lo.s32 %r_limit, %r_chunk, 972;
    mov.s32 %r_idx, %r_tid;
$L_ldloop:
    setp.lt.s32 %p0, %r_idx, %r_limit;
    @!%p0 bra $L_lddone;
    div.s32 %r_c, %r_idx, 972;
    rem.s32 %r_rem, %r_idx, 972;
    div.s32 %r_kz, %r_rem, 324;
    rem.s32 %r_r2, %r_rem, 324;
    div.s32 %r_row, %r_r2, 18;
    rem.s32 %r_col, %r_r2, 18;
    sub.s32 %r_z, %r_oz, %r_kz;
    add.s32 %r_y, %r_oy0, %r_row;
    sub.s32 %r_y, %r_y, 2;
    add.s32 %r_x, %r_ox0, %r_col;
    sub.s32 %r_x, %r_x, 2;
    mov.f32 %xv, 0f00000000;
    setp.lt.s32 %p0, %r_z, 0;
    setp.ge.s32 %p1, %r_z, %r_D;
    or.pred %p0, %p0, %p1;
    setp.lt.s32 %p1, %r_y, 0;
    or.pred %p0, %p0, %p1;
    setp.ge.s32 %p1, %r_y, %r_H;
    or.pred %p0, %p0, %p1;
    setp.lt.s32 %p1, %r_x, 0;
    or.pred %p0, %p0, %p1;
    setp.ge.s32 %p1, %r_x, %r_W;
    or.pred %p0, %p0, %p1;
    @%p0 bra $L_st_smem;
    add.s32 %r_ci, %r_ci0, %r_c;
    mul.lo.s32 %r_off, %r_bn, %r_CI;
    add.s32 %r_off, %r_off, %r_ci;
    mul.lo.s32 %r_off, %r_off, %r_D;
    add.s32 %r_off, %r_off, %r_z;
    mul.lo.s32 %r_off, %r_off, %r_H;
    add.s32 %r_off, %r_off, %r_y;
    mul.lo.s32 %r_off, %r_off, %r_W;
    add.s32 %r_off, %r_off, %r_x;
    mul.wide.s32 %addr, %r_off, 4;
    add.u64 %addr, %xptr, %addr;
    ld.global.f32 %xv, [%addr];
$L_st_smem:
    mul.lo.s32 %r_off, %r_idx, 4;
    add.u32 %r_ain, %r_shin, %r_off;
    st.shared.f32 [%r_ain], %xv;
    add.s32 %r_idx, %r_idx, 256;
    bra $L_ldloop;
$L_lddone:
    // ---- stage weights for 4 cin x 4 cout into shared ----
    // ---- stage weights for 4 cin x 8 cout into shared ----
    // Layout is cout-fastest: smem_w[c*216 + tap*8 + j] so the compute
    // loop fetches all 8 output-channel weights with two ld.shared.v4.
    mul.lo.s32 %r_limit, %r_chunk, 216;
    mov.s32 %r_idx, %r_tid;
$L_wloop:
    setp.lt.s32 %p0, %r_idx, %r_limit;
    @!%p0 bra $L_wdone;
    div.s32 %r_c, %r_idx, 216;
    rem.s32 %r_rem, %r_idx, 216;
    and.b32 %r_j, %r_rem, 7;
    shr.s32 %r_rem, %r_rem, 3;
    add.s32 %r_co, %r_co0, %r_j;
    mov.f32 %xv, 0f00000000;
    setp.ge.s32 %p0, %r_co, %r_CO;
    @%p0 bra $L_wst;
    add.s32 %r_ci, %r_ci0, %r_c;
    mul.lo.s32 %r_off, %r_ci, %r_CO;
    add.s32 %r_off, %r_off, %r_co;
    mul.lo.s32 %r_off, %r_off, 27;
    add.s32 %r_off, %r_off, %r_rem;
    mul.wide.s32 %addr, %r_off, 4;
    add.u64 %addr, %wptr, %addr;
    ld.global.f32 %xv, [%addr];
$L_wst:
    mul.lo.s32 %r_off, %r_idx, 4;
    add.u32 %r_ain, %r_shw, %r_off;
    st.shared.f32 [%r_ain], %xv;
    add.s32 %r_idx, %r_idx, 256;
    bra $L_wloop;
$L_wdone:
    bar.sync 0;
    @!%p_inb bra $L_compute_done;
    mov.s32 %r_c, 0;
$L_cloop:
    setp.lt.s32 %p0, %r_c, %r_chunk;
    @!%p0 bra $L_compute_done;
    mov.s32 %r_kz, 0;
$L_kzloop:
    setp.lt.s32 %p0, %r_kz, 3;
    @!%p0 bra $L_kzdone;
    mul.lo.s32 %r_sbase, %r_c, 3;
    add.s32 %r_sbase, %r_sbase, %r_kz;
    mul.lo.s32 %r_sbase, %r_sbase, 324;
    mul.lo.s32 %r_wbase, %r_c, 27;
    mov.s32 %r_ky, 0;
$L_kyloop:
    setp.lt.s32 %p0, %r_ky, 3;
    @!%p0 bra $L_kydone;
    sub.s32 %r_row, %r_ty, %r_ky;
    add.s32 %r_row, %r_row, 2;
    mul.lo.s32 %r_rowoff, %r_row, 18;
    add.s32 %r_rowoff, %r_rowoff, %r_sbase;
    mov.s32 %r_kx, 0;
$L_kxloop:
    setp.lt.s32 %p0, %r_kx, 3;
    @!%p0 bra $L_kxdone;
    sub.s32 %r_sidx, %r_tx, %r_kx;
    add.s32 %r_sidx, %r_sidx, 2;
    add.s32 %r_sidx, %r_sidx, %r_rowoff;
    mul.lo.s32 %r_off, %r_sidx, 4;
    add.u32 %r_ain, %r_shin, %r_off;
    ld.shared.f32 %xv, [%r_ain];
    mul.lo.s32 %r_tmp2, %r_kz, 9;
    add.s32 %r_widx, %r_wbase, %r_tmp2;
    mul.lo.s32 %r_tmp2, %r_ky, 3;
    add.s32 %r_widx, %r_widx, %r_tmp2;
    add.s32 %r_widx, %r_widx, %r_kx;
    shl.b32 %r_off, %r_widx, 5;
    add.u32 %r_ain, %r_shw, %r_off;
    ld.shared.v4.f32 {%wv0, %wv1, %wv2, %wv3}, [%r_ain];
    ld.shared.v4.f32 {%wv4, %wv5, %wv6, %wv7}, [%r_ain+16];
    fma.rn.f32 %acc0, %xv, %wv0, %acc0;
    fma.rn.f32 %acc1, %xv, %wv1, %acc1;
    fma.rn.f32 %acc2, %xv, %wv2, %acc2;
    fma.rn.f32 %acc3, %xv, %wv3, %acc3;
    fma.rn.f32 %acc4, %xv, %wv4, %acc4;
    fma.rn.f32 %acc5, %xv, %wv5, %acc5;
    fma.rn.f32 %acc6, %xv, %wv6, %acc6;
    fma.rn.f32 %acc7, %xv, %wv7, %acc7;
    add.s32 %r_kx, %r_kx, 1;
    bra $L_kxloop;
$L_kxdone:
    add.s32 %r_ky, %r_ky, 1;
    bra $L_kyloop;
$L_kydone:
    add.s32 %r_kz, %r_kz, 1;
    bra $L_kzloop;
$L_kzdone:
    add.s32 %r_c, %r_c, 1;
    bra $L_cloop;
$L_compute_done:
    bar.sync 0;
    add.s32 %r_ci0, %r_ci0, 4;
    bra $L_chunk_loop;
$L_epilogue:
    @!%p_inb bra $L_ret;
    mul.lo.s32 %r_hw, %r_HO, %r_WO;
    mul.lo.s32 %r_dhw, %r_DO, %r_hw;
    mul.lo.s32 %r_off, %r_oz, %r_hw;
    mul.lo.s32 %r_tmp, %r_oy, %r_WO;
    add.s32 %r_off, %r_off, %r_tmp;
    add.s32 %r_off, %r_off, %r_ox;
    mul.lo.s32 %r_tmp, %r_bn, %r_CO;
    mul.lo.s32 %r_tmp, %r_tmp, %r_dhw;
    add.s32 %r_sbase, %r_tmp, %r_off;
    setp.eq.s32 %p_bias, %r_BIAS, 0;
    mov.s32 %r_co, %r_co0;
    @%p_bias bra $L_e0st;
    mul.wide.s32 %addr, %r_co, 4;
    add.u64 %baddr, %bptr, %addr;
    ld.global.f32 %bv, [%baddr];
    add.f32 %acc0, %acc0, %bv;
$L_e0st:
    mul.lo.s32 %r_tmp, %r_co, %r_dhw;
    add.s32 %r_tmp, %r_tmp, %r_sbase;
    mul.wide.s32 %addr, %r_tmp, 4;
    add.u64 %yaddr, %yptr, %addr;
    st.global.f32 [%yaddr], %acc0;
    add.s32 %r_co, %r_co0, 1;
    setp.ge.s32 %p0, %r_co, %r_CO;
    @%p0 bra $L_ret;
    @%p_bias bra $L_e1st;
    mul.wide.s32 %addr, %r_co, 4;
    add.u64 %baddr, %bptr, %addr;
    ld.global.f32 %bv, [%baddr];
    add.f32 %acc1, %acc1, %bv;
$L_e1st:
    mul.lo.s32 %r_tmp, %r_co, %r_dhw;
    add.s32 %r_tmp, %r_tmp, %r_sbase;
    mul.wide.s32 %addr, %r_tmp, 4;
    add.u64 %yaddr, %yptr, %addr;
    st.global.f32 [%yaddr], %acc1;
    add.s32 %r_co, %r_co0, 2;
    setp.ge.s32 %p0, %r_co, %r_CO;
    @%p0 bra $L_ret;
    @%p_bias bra $L_e2st;
    mul.wide.s32 %addr, %r_co, 4;
    add.u64 %baddr, %bptr, %addr;
    ld.global.f32 %bv, [%baddr];
    add.f32 %acc2, %acc2, %bv;
$L_e2st:
    mul.lo.s32 %r_tmp, %r_co, %r_dhw;
    add.s32 %r_tmp, %r_tmp, %r_sbase;
    mul.wide.s32 %addr, %r_tmp, 4;
    add.u64 %yaddr, %yptr, %addr;
    st.global.f32 [%yaddr], %acc2;
    add.s32 %r_co, %r_co0, 3;
    setp.ge.s32 %p0, %r_co, %r_CO;
    @%p0 bra $L_ret;
    @%p_bias bra $L_e3st;
    mul.wide.s32 %addr, %r_co, 4;
    add.u64 %baddr, %bptr, %addr;
    ld.global.f32 %bv, [%baddr];
    add.f32 %acc3, %acc3, %bv;
$L_e3st:
    mul.lo.s32 %r_tmp, %r_co, %r_dhw;
    add.s32 %r_tmp, %r_tmp, %r_sbase;
    mul.wide.s32 %addr, %r_tmp, 4;
    add.u64 %yaddr, %yptr, %addr;
    st.global.f32 [%yaddr], %acc3;
    add.s32 %r_co, %r_co0, 4;
    setp.ge.s32 %p0, %r_co, %r_CO;
    @%p0 bra $L_ret;
    @%p_bias bra $L_e4st;
    mul.wide.s32 %addr, %r_co, 4;
    add.u64 %baddr, %bptr, %addr;
    ld.global.f32 %bv, [%baddr];
    add.f32 %acc4, %acc4, %bv;
$L_e4st:
    mul.lo.s32 %r_tmp, %r_co, %r_dhw;
    add.s32 %r_tmp, %r_tmp, %r_sbase;
    mul.wide.s32 %addr, %r_tmp, 4;
    add.u64 %yaddr, %yptr, %addr;
    st.global.f32 [%yaddr], %acc4;
    add.s32 %r_co, %r_co0, 5;
    setp.ge.s32 %p0, %r_co, %r_CO;
    @%p0 bra $L_ret;
    @%p_bias bra $L_e5st;
    mul.wide.s32 %addr, %r_co, 4;
    add.u64 %baddr, %bptr, %addr;
    ld.global.f32 %bv, [%baddr];
    add.f32 %acc5, %acc5, %bv;
$L_e5st:
    mul.lo.s32 %r_tmp, %r_co, %r_dhw;
    add.s32 %r_tmp, %r_tmp, %r_sbase;
    mul.wide.s32 %addr, %r_tmp, 4;
    add.u64 %yaddr, %yptr, %addr;
    st.global.f32 [%yaddr], %acc5;
    add.s32 %r_co, %r_co0, 6;
    setp.ge.s32 %p0, %r_co, %r_CO;
    @%p0 bra $L_ret;
    @%p_bias bra $L_e6st;
    mul.wide.s32 %addr, %r_co, 4;
    add.u64 %baddr, %bptr, %addr;
    ld.global.f32 %bv, [%baddr];
    add.f32 %acc6, %acc6, %bv;
$L_e6st:
    mul.lo.s32 %r_tmp, %r_co, %r_dhw;
    add.s32 %r_tmp, %r_tmp, %r_sbase;
    mul.wide.s32 %addr, %r_tmp, 4;
    add.u64 %yaddr, %yptr, %addr;
    st.global.f32 [%yaddr], %acc6;
    add.s32 %r_co, %r_co0, 7;
    setp.ge.s32 %p0, %r_co, %r_CO;
    @%p0 bra $L_ret;
    @%p_bias bra $L_e7st;
    mul.wide.s32 %addr, %r_co, 4;
    add.u64 %baddr, %bptr, %addr;
    ld.global.f32 %bv, [%baddr];
    add.f32 %acc7, %acc7, %bv;
$L_e7st:
    mul.lo.s32 %r_tmp, %r_co, %r_dhw;
    add.s32 %r_tmp, %r_tmp, %r_sbase;
    mul.wide.s32 %addr, %r_tmp, 4;
    add.u64 %yaddr, %yptr, %addr;
    st.global.f32 [%yaddr], %acc7;
$L_ret:
    ret;
    // ============================================================
    // Generic fallback path (K != 3): original direct kernel.
    // ============================================================
$D_setup:
    mov.u32 %r_ntid, %ntid.x;
    mov.u32 %r_ctaid, %ctaid.x;
    mov.u32 %r_tid0, %tid.x;
    mad.lo.s32 %r_tid, %r_ctaid, %r_ntid, %r_tid0;
    mul.lo.s32 %r_hw, %r_HO, %r_WO;
    mul.lo.s32 %r_dhw, %r_DO, %r_hw;
    mul.lo.s32 %r_chw, %r_CO, %r_dhw;
    mul.lo.s32 %r_total, %r_N, %r_chw;
    setp.ge.s32 %p_done, %r_tid, %r_total;
    @%p_done bra $D_done;
    rem.s32 %r_ox, %r_tid, %r_WO;
    div.s32 %r_tmp, %r_tid, %r_WO;
    rem.s32 %r_oy, %r_tmp, %r_HO;
    div.s32 %r_tmp, %r_tmp, %r_HO;
    rem.s32 %r_oz, %r_tmp, %r_DO;
    div.s32 %r_tmp, %r_tmp, %r_DO;
    rem.s32 %r_co, %r_tmp, %r_CO;
    div.s32 %r_bn, %r_tmp, %r_CO;
    mov.f32 %acc, 0f00000000;
    mov.s32 %r_ci, 0;
$D_ci_loop:
    setp.lt.s32 %p_ci, %r_ci, %r_CI;
    @!%p_ci bra $D_after_channels;
    mov.s32 %r_kz, 0;
$D_kz_loop:
    setp.lt.s32 %p_kz, %r_kz, %r_K;
    @!%p_kz bra $D_kz_next;
    sub.s32 %r_z, %r_oz, %r_kz;
    setp.lt.s32 %p_zlo, %r_z, 0;
    @%p_zlo bra $D_kz_next;
    setp.ge.s32 %p_zhi, %r_z, %r_D;
    @%p_zhi bra $D_ky_next;
    mov.s32 %r_ky, 0;
$D_ky_loop:
    setp.lt.s32 %p_ky, %r_ky, %r_K;
    @!%p_ky bra $D_ky_next;
    sub.s32 %r_y, %r_oy, %r_ky;
    setp.lt.s32 %p_ylo, %r_y, 0;
